package cn.iocoder.yudao.module.heritage.dal.mysql;
import cn.iocoder.yudao.framework.mybatis.core.mapper.BaseMapperX; import cn.iocoder.yudao.module.heritage.dal.dataobject.ServiceBookingDO; import cn.iocoder.yudao.module.heritage.service.BookingRow; import org.apache.ibatis.annotations.*; import java.util.List;
@Mapper public interface ServiceBookingMapper extends BaseMapperX<ServiceBookingDO> {
 @Select("SELECT * FROM heritage_service_booking WHERE user_id=#{userId} AND schedule_id=#{scheduleId} AND status IN (0,1) AND deleted=0 LIMIT 1") ServiceBookingDO selectActive(Long userId,Long scheduleId); @Select("SELECT * FROM heritage_service_booking WHERE id=#{id} AND deleted=0 LIMIT 1 FOR UPDATE") ServiceBookingDO selectForUpdate(Long id);
 @Select("SELECT b.id AS bookingId,b.status,b.people_count AS peopleCount,b.contact_name AS contactName,b.contact_phone AS contactPhone,b.create_time AS createTime,b.service_id AS serviceId,s.title AS serviceTitle,s.cover_url AS coverUrl,ps.code AS systemCode,ps.name AS systemName,b.schedule_id AS scheduleId,sc.start_time AS startTime,sc.end_time AS endTime,sc.location AS location FROM heritage_service_booking b JOIN heritage_service s ON s.id=b.service_id JOIN heritage_product_system ps ON ps.id=s.product_system_id JOIN heritage_service_schedule sc ON sc.id=b.schedule_id WHERE b.user_id=#{userId} AND b.deleted=0 ORDER BY b.create_time DESC LIMIT #{offset},#{limit}") List<BookingRow> selectMy(Long userId,long offset,int limit);
 @Select("SELECT COUNT(1) FROM heritage_service_booking WHERE user_id=#{userId} AND deleted=0") long countMy(Long userId);
 @Update("UPDATE heritage_service_booking SET status=#{status},updater=#{updater},update_time=NOW() WHERE id=#{id} AND user_id=#{userId} AND status IN (0,1) AND deleted=0") int cancel(Long id,Long userId,int status,String updater); @Update("UPDATE heritage_service_booking SET status=#{toStatus},updater=#{updater},update_time=NOW() WHERE id=#{id} AND status=#{fromStatus} AND deleted=0") int updateStatus(Long id,int fromStatus,int toStatus,String updater);
}
